solution.solution.c:
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int count_words(const char *s)
{
    int words = 0;
    int inside = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (isspace((unsigned char)s[i])) {
            inside = 0;
        } else if (!inside) {
            inside = 1;
            words++;
        }
    }
    return words;
}

int starts_with(const char *s, const char *prefix)
{
    return strncmp(s, prefix, strlen(prefix)) == 0;
}

void format_name(char *out, size_t size, const char *first, const char *last)
{
    snprintf(out, size, "%s, %s", last, first);
}

int parse_number(const char *s, long *result)
{
    char *end = NULL;
    long value = strtol(s, &end, 10);
    if (end == s) return 0;
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0') return 0;
    *result = value;
    return 1;
}

unitTests:
TEST("counting words") { CHECK_EQ(count_words("the quick brown fox"), 4); CHECK_EQ(count_words("  spaced   out  "), 2); CHECK_EQ(count_words(""), 0); CHECK_EQ(count_words("   "), 0); CHECK_EQ(count_words("one\ttwo\nthree"), 3); }
TEST("prefixes") { CHECK(starts_with("prefix-rest", "prefix")); CHECK(starts_with("abc", "")); CHECK(starts_with("abc", "abc")); CHECK(!starts_with("ab", "abc")); CHECK(!starts_with("xabc", "abc")); }
TEST("formatting a name") { char out[32]; format_name(out, sizeof out, "Ada", "Lovelace"); CHECK_STR(out, "Lovelace, Ada"); }
TEST("a name that does not fit is cut, not overflowed") { char out[6]; format_name(out, sizeof out, "Ada", "Lovelace"); CHECK_STR(out, "Lovel"); }
TEST("parsing numbers") { long n = 0; CHECK(parse_number("42", &n)); CHECK_EQ(n, 42L); CHECK(parse_number("  -17  ", &n)); CHECK_EQ(n, -17L); CHECK(!parse_number("cat", &n)); CHECK(!parse_number("12abc", &n)); CHECK(!parse_number("", &n)); }

